<?php require '../../includes/config.php';require '../../includes/layout.php';require_login(['student']);if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$category=trim($_POST['category']);$topic=trim($_POST['topic']);$subject=trim($_POST['subject']);$description=trim($_POST['description']);if(!$category||!$topic||!$subject||!$description){$error='Please complete all ticket fields.';}else{$ref=generate_ref($conn);$stmt=$conn->prepare('INSERT INTO tickets(ref_number,student_id,category,topic,subject,description) VALUES(?,?,?,?,?,?)');$uid=$_SESSION['user']['id'];$stmt->bind_param('sissss',$ref,$uid,$category,$topic,$subject,$description);$stmt->execute();flash('ticket_ref',$ref);redirect('tickets.php');}}student_shell('Submit Complaint','new');?><div class="page-header"><h2>Submit a Complaint or Request</h2></div><div class="content-card"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div><label class="label">Issue or Request Type</label><select name="category" required><option value="">Select type</option><option>Complaint</option><option>Service Request</option><option>Information Request</option><option>Suggestion</option></select></div><div><label class="label">Topic</label><select name="topic" required><option value="">Select topic</option><option>Academic Issues</option><option>Registration & Records</option><option>ICT & Internet</option><option>Fees & Accounts</option><option>Hostel & Welfare</option><option>Library</option><option>Health Services</option><option>Staff Conduct</option><option>Security</option><option>Other</option></select></div><div class="full"><label class="label">Subject</label><input name="subject" maxlength="180" required></div><div class="full"><label class="label">Describe your issue or request</label><textarea name="description" rows="7" required></textarea></div></div><?php if(!empty($error))echo'<div class="alert alert-error">'.e($error).'</div>';?><button class="btn btn-primary">Submit Ticket</button></form></div><?php dashboard_footer(); ?>